1	import {
2	  BottomSheetModal,
3	  type BottomSheetModalProps,
4	} from "@gorhom/bottom-sheet";
5	import { animateSequence, Block } from "@prototyp/skeletor";
6	import {
7	  forwardRef,
8	  type ReactNode,
9	  useCallback,
10	  useEffect,
11	  useImperativeHandle,
12	  useRef,
13	} from "react";
14	import { Dimensions, StyleSheet } from "react-native";
15	import { Colors } from "shared/styles";
16	
17	const { height, width } = Dimensions.get("screen");
18	
19	export interface AppBottomSheetRef {
20	  close: () => void;
21	}
22	
23	interface Props {
24	  isOpen: boolean;
25	  children: ReactNode;
26	  maxContentSize?: number;
27	  enableContentPanningGesture?: boolean;
28	  keyboardBehavior?: BottomSheetModalProps["keyboardBehavior"];
29	  keyboardBlurBehavior?: BottomSheetModalProps["keyboardBlurBehavior"];
30	  android_keyboardInputMode?: BottomSheetModalProps["android_keyboardInputMode"];
31	  onClose: () => void;
32	}
33	
34	export const AppBottomSheet = forwardRef<AppBottomSheetRef, Props>(
35	  (
36	    {
37	      isOpen,
38	      children,
39	      maxContentSize,
40	      enableContentPanningGesture,
41	      keyboardBehavior,
42	      keyboardBlurBehavior,
43	      android_keyboardInputMode,
44	      onClose,
45	    },
46	    ref,
47	  ) => {
48	    const sheetRef = useRef<BottomSheetModal>(null);
49	    const fadeIn = useRef(
50	      animateSequence({ opacity: [0, 1] }, { duration: 200 }),
51	    ).current;
52	    const isClosingRef = useRef(false);
53	
54	    const handleDismiss = useCallback(() => {
55	      if (isClosingRef.current) return;
56	      isClosingRef.current = true;
57	      fadeIn.reverse(() => {
58	        isClosingRef.current = false;
59	        onClose();
60	      });
61	    }, [fadeIn, onClose]);
62	
63	    useImperativeHandle(ref, () => ({
64	      close: () => {
65	        handleDismiss();
66	        sheetRef.current?.dismiss();
67	      },
68	    }));
69	
70	    useEffect(() => {
71	      if (!isOpen) return;
72	      fadeIn.start();
73	      sheetRef.current?.present();
74	    }, [isOpen, fadeIn]);
75	
76	    if (!isOpen) return null;
77	
78	    return (
79	      <Block
80	        absolute
81	        width={width}
82	        height="100%"
83	        offsets={{ left: 0, top: 0 }}
84	        animations={fadeIn.animations}
85	        zIndex={9999}
86	        background={Colors.black70}
87	      >
88	        <BottomSheetModal
89	          ref={sheetRef}
90	          handleStyle={styles.handle}
91	          handleIndicatorStyle={styles.handleIndicator}
92	          backgroundStyle={styles.background}
93	          enablePanDownToClose
94	          enableDynamicSizing
95	          maxDynamicContentSize={maxContentSize ?? height - 200}
96	          onDismiss={handleDismiss}
97	          enableContentPanningGesture={enableContentPanningGesture}
98	          keyboardBehavior={keyboardBehavior}
99	          keyboardBlurBehavior={keyboardBlurBehavior}
100	          android_keyboardInputMode={android_keyboardInputMode}
101	        >
102	          {children}
103	        </BottomSheetModal>
104	      </Block>
105	    );
106	  },
107	);
108	
109	const styles = StyleSheet.create({
110	  background: {
111	    backgroundColor: Colors.blackMinus1,
112	    borderTopLeftRadius: 24,
113	    borderTopRightRadius: 24,
114	  },
115	  handle: {
116	    borderWidth: 1,
117	    borderBottomWidth: 0,
118	    borderTopLeftRadius: 24,
119	    borderTopRightRadius: 24,
120	    paddingHorizontal: 12,
121	    paddingTop: 12,
122	    paddingBottom: 24,
123	  },
124	  handleIndicator: {
125	    width: 84,
126	    height: 4,
127	    backgroundColor: Colors.white50,
128	  },
129	});
